1	import { Block, Text } from "@prototyp/skeletor";
2	import {
3	  EmbeddedEventDetails_Tags,
4	  type EventTimelineItem,
5	  type MediaSourceInterface,
6	  MessageLikeEventContent_Tags,
7	  MessageType_Tags,
8	  MsgLikeKind_Tags,
9	  ProfileDetails_Tags,
10	  TimelineEventType_Tags,
11	  TimelineItemContent_Tags,
12	} from "@unomed/react-native-matrix-sdk";
13	import { useSetAtom } from "jotai";
14	import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
15	import {
16	  cleanMentions,
17	  getEventTextContent,
18	  getMessageTextContent,
19	} from "modules/matrix-client/utils";
20	import { TimelineAtoms } from "modules/timeline/jotai";
21	import { TimelineService } from "modules/timeline/service/TimelineService";
22	import { type FC, useCallback, useEffect, useMemo, useState } from "react";
23	import { Dimensions, Image, StyleSheet } from "react-native";
24	import { MessageTimestamp, PinIndicator, SeenBy } from "shared/components";
25	import { Colors, TextSize } from "shared/styles";
26	import { MentionText } from "../mention-text";
27	import { MessageLongPressWrapper } from "../message-long-press-wrapper";
28	import { MessageReactionsOverlay } from "../message-reactions-overlay";
29	import { MessageSender } from "../message-sender";
30	import { ReplyPayload } from "../reply-paylaod";
31	
32	interface Props {
33	  roomId: string;
34	  event: EventTimelineItem;
35	  isPreviousSameSender: boolean;
36	  onMemberPress?: (member: MemberDetailsPayload) => void;
37	}
38	
39	const MAX_WIDTH = Dimensions.get("window").width - 60;
40	
41	// Parse <a href="https://matrix.to/#/@user:server">@DisplayName</a> tags from
42	// formatted_body HTML into a lowercase-displayName → userId map.
43	// This is the sync fast path — no profile loading needed.
44	const parseMentionMapFromHtml = (html: string): Map<string, string> => {
45	  const regex =
46	    /<a[^>]+href="https:\/\/matrix\.to\/#\/(@[^"]+)"[^>]*>@?([^<]+)<\/a>/gi;
47	  const matches = Array.from(html.matchAll(regex));
48	  return new Map(matches.map((m) => [m[2].toLowerCase(), m[1]]));
49	};
50	
51	export const TextMessage: FC<Props> = ({
52	  roomId,
53	  event,
54	  isPreviousSameSender,
55	  onMemberPress,
56	}) => {
57	  const [messageWidth, setMessageWidth] = useState(116);
58	  const isUser = event.isOwn;
59	  const sender = event.senderProfile;
60	  const senderId = event.sender;
61	  const seenByUsers = TimelineService.getReadReceiptUsers(event);
62	  const [fetchedReplyPayload, setFetchedReplyPayload] =
63	    useState<TimelineReplyPayload | null>(null);
64	  const [mentionMap, setMentionMap] = useState<Map<string, string>>(new Map());
65	  // Some clients (Element X) put raw markdown links in the body:
66	  // [@Name](matrix.to/#/@user:server)  — link text has @
67	  // [Name](matrix.to/#/@user:server)   — link text without @
68	  // Detect by the /#/@ pattern in the URL (user permalink) and normalize to @Name.
69	  const content = cleanMentions(getEventTextContent(event));
70	  const setScrollToEventId = useSetAtom(TimelineAtoms.scrollToEventId);
71	
72	  const { formattedBody, mentionUserIds, isEdited } = useMemo(() => {
73	    if (event.content.tag !== TimelineItemContent_Tags.MsgLike)
74	      return { formattedBody: undefined, mentionUserIds: [], isEdited: false };
75	    const kind = event.content.inner.content.kind;
76	    if (kind?.tag !== MsgLikeKind_Tags.Message) {
77	      return { formattedBody: undefined, mentionUserIds: [], isEdited: false };
78	    }
79	    const msgType = kind.inner.content.msgType;
80	    const html =
81	      msgType?.tag === MessageType_Tags.Text
82	        ? msgType.inner.content.formatted?.body
83	        : undefined;
84	    return {
85	      formattedBody: html,
86	      mentionUserIds: kind.inner.content.mentions?.userIds ?? [],
87	      isEdited: kind.inner.content.isEdited,
88	    };
89	  }, [event]);
90	
91	  const replyPayload = useMemo(() => {
92	    if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return null;
93	
94	    const inReplyTo = event.content.inner.content.inReplyTo;
95	
96	    if (!inReplyTo) return null;
97	
98	    const eventDetails = inReplyTo.event();
99	
100	    if (eventDetails.tag === EmbeddedEventDetails_Tags.Unavailable) {
101	      return {
102	        eventId: inReplyTo.eventId(),
103	        senderName: "",
104	        content: "",
105	        isUnavailable: true,
106	      };
107	    }
108	
109	    if (eventDetails.tag !== EmbeddedEventDetails_Tags.Ready) return null;
110	
111	    const senderName =
112	      eventDetails.inner.senderProfile.tag === ProfileDetails_Tags.Ready
113	        ? (eventDetails.inner.senderProfile.inner.displayName ??
114	          eventDetails.inner.sender)
115	        : eventDetails.inner.sender;
116	
117	    let mediaSource: { source: MediaSourceInterface; mimetype: string } | null =
118	      null;
119	    const replyContent = eventDetails.inner.content;
120	
121	    if (replyContent.tag === TimelineItemContent_Tags.MsgLike) {
122	      const kind = replyContent.inner.content.kind;
123	      if (kind?.tag === MsgLikeKind_Tags.Message) {
124	        const msgType = kind.inner.content.msgType;
125	        if (msgType?.tag === MessageType_Tags.Image) {
126	          mediaSource = {
127	            source: msgType.inner.content.source,
128	            mimetype: msgType.inner.content.info?.mimetype || "image/jpeg",
129	          };
130	        }
131	        if (msgType?.tag === MessageType_Tags.Video) {
132	          mediaSource = {
133	            source: msgType.inner.content.source,
134	            mimetype: msgType.inner.content.info?.mimetype || "video/mp4",
135	          };
136	        }
137	      }
138	    }
139	
140	    return {
141	      eventId: inReplyTo.eventId(),
142	      senderName,
143	      content: getMessageTextContent(eventDetails.inner.content),
144	      mediaSource,
145	    };
146	  }, [event]);
147	
148	  const handleReplyPress = useCallback(() => {
149	    if (replyPayload) setScrollToEventId(replyPayload.eventId);
150	  }, [replyPayload, setScrollToEventId]);
151	
152	  useEffect(() => {
153	    if (!replyPayload?.isUnavailable) {
154	      setFetchedReplyPayload(null);
155	      return;
156	    }
157	
158	    const room = MatrixCore.getRoom(roomId);
159	    const client = MatrixCore.getClient();
160	
161	    room
162	      .loadOrFetchEvent(replyPayload.eventId)
163	      .then(async (fetchedEvent) => {
164	        const senderId = fetchedEvent.senderId();
165	
166	        let senderName = senderId;
167	        let mediaSource: {
168	          source: MediaSourceInterface;
169	          mimetype: string;
170	        } | null = null;
171	        try {
172	          const profile = await client.getProfile(senderId);
173	          senderName = profile.displayName ?? senderId;
174	        } catch {}
175	
176	        const eventType = fetchedEvent.eventType();
177	        let content = "";
178	        if (eventType.tag === TimelineEventType_Tags.MessageLike) {
179	          const msgContent = eventType.inner.content;
180	          if (msgContent.tag === MessageLikeEventContent_Tags.RoomMessage) {
181	            const msgType = msgContent.inner.messageType;
182	            if (msgType.tag === MessageType_Tags.Text) {
183	              content = msgType.inner.content.body;
184	            } else if (
185	              msgType.tag === MessageType_Tags.Audio ||
186	              msgType.tag === MessageType_Tags.File
187	            ) {
188	              content = msgType.inner.content.filename;
189	            } else if (
190	              msgType.tag === MessageType_Tags.Image ||
191	              msgType.tag === MessageType_Tags.Video
192	            ) {
193	              mediaSource = {
194	                source: msgType.inner.content.source,
195	                mimetype: msgType.inner.content.info?.mimetype || "image/jpeg",
196	              };
197	              content = msgType.inner.content.filename;
198	            }
199	          }
200	        }
201	
202	        setFetchedReplyPayload({
203	          eventId: replyPayload.eventId,
204	          senderName,
205	          content,
206	          mediaSource,
207	        });
208	      })
209	      .catch();
210	  }, [replyPayload?.isUnavailable, replyPayload?.eventId, roomId, event]);
211	
212	  useEffect(() => {
213	    // Fast path: extract mention map directly from formatted_body HTML
214	    if (formattedBody) {
215	      const map = parseMentionMapFromHtml(formattedBody);
216	      if (map.size > 0) {
217	        setMentionMap(map);
218	        return;
219	      }
220	    }
221	
222	    // Fallback: load profiles for mentioned user IDs (messages without formatted_body)
223	    if (!mentionUserIds.length) return;
224	    const client = MatrixCore.getClient();
225	    Promise.allSettled(mentionUserIds.map((id) => client.getProfile(id))).then(
226	      (results) => {
227	        const map = new Map<string, string>();
228	        results.forEach((result, i) => {
229	          const userId = mentionUserIds[i];
230	          const displayName =
231	            result.status === "fulfilled"
232	              ? (result.value.displayName ?? userId)
233	              : userId;
234	          map.set(displayName.toLowerCase(), userId);
235	        });
236	        setMentionMap(map);
237	      },
238	    );
239	  }, [formattedBody, mentionUserIds]);
240	
241	  return (
242	    <Block
243	      align={isUser ? "flex-end" : "flex-start"}
244	      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
245	    >
246	      <MessageSender
247	        sender={sender}
248	        senderId={senderId}
249	        isUser={isUser}
250	        isPreviousSameSender={isPreviousSameSender}
251	        onMemberPress={onMemberPress}
252	      />
253	      <MessageLongPressWrapper event={event} content={content}>
254	        <Block flexDirection={isUser ? "row-reverse" : "row"}>
255	          <Block
256	            paddings={12}
257	            background={isUser ? Colors.primary : Colors.message}
258	            border={{ borderRadius: 24 }}
259	            align="stretch"
260	            gap={12}
261	            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
262	            maxWidth={MAX_WIDTH}
263	          >
264	            <ReplyPayload
265	              replyPayload={fetchedReplyPayload ?? replyPayload}
266	              onPress={handleReplyPress}
267	            />
268	            <Block
269	              flexDirection={isUser ? "row-reverse" : "row"}
270	              align="flex-end"
271	              justify="space-between"
272	              flex={{ flexWrap: "wrap" }}
273	              gap={{ row: 4, col: 16 }}
274	              // Some short strings (e.ag., "aa", "ai") wrap unexpectedly, while others ("dd", "a") do not.
275	              // Add this value to prevent unwanted wrapping for short text.
276	              minWidth={116}
277	            >
278	              {mentionMap.size > 0 ? (
279	                <MentionText
280	                  isUser={isUser}
281	                  body={content}
282	                  mentionMap={mentionMap}
283	                  onMentionPress={onMemberPress}
284	                />
285	              ) : (
286	                <Text size={TextSize.small} color="white">
287	                  {content}
288	                </Text>
289	              )}
290	              <MessageTimestamp
291	                event={event}
292	                isUser={isUser}
293	                isEdited={isEdited}
294	              />
295	            </Block>
296	            {isPreviousSameSender && (
297	              <Block
298	                absolute
299	                offsets={
300	                  isUser
301	                    ? {
302	                        right: 6,
303	                        bottom: 2,
304	                      }
305	                    : {
306	                        left: 6,
307	                        bottom: 2,
308	                      }
309	                }
310	              >
311	                <Image
312	                  source={
313	                    isUser
314	                      ? require("assets/icons/polygon.png")
315	                      : require("assets/icons/guest-polygon.png")
316	                  }
317	                  width={7}
318	                  height={6}
319	                  style={styles.polygon}
320	                />
321	              </Block>
322	            )}
323	          </Block>
324	          <PinIndicator event={event} />
325	        </Block>
326	      </MessageLongPressWrapper>
327	      <MessageReactionsOverlay event={event} roomId={roomId} isUser={isUser} />
328	      <SeenBy users={seenByUsers} messageWidth={messageWidth} isUser={isUser} />
329	    </Block>
330	  );
331	};
332	
333	const styles = StyleSheet.create({
334	  polygon: {
335	    width: 7,
336	    height: 6,
337	  },
338	});
